private static NewReservation readNewReservation(Context ctx) {
    CreateReservationRequest body;
    try {
        body = ctx.bodyAsClass(CreateReservationRequest.class);
    } catch (Exception unreadableBody) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
    }
    if (body == null
            || body.roomNumber() == null
            || isBlank(body.guestName())
            || isBlank(body.guestEmail())
            || body.checkIn() == null
            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
    }

    int identificationTypes = 0;
    if (!isBlank(body.guestCpf())) identificationTypes++;
    if (!isBlank(body.companyCnpj())) identificationTypes++;
    if (!isBlank(body.guestPassport())) identificationTypes++;

    if (identificationTypes != 1) {
        throw new HotelException(
                ErrorCode.INVALID_REQUEST,
                "provide exactly one of: guestCpf, companyCnpj (with companyName), or guestPassport (with guestCountry)");
    }

    if (!isBlank(body.companyCnpj()) && isBlank(body.companyName())) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "companyName is required when companyCnpj is provided");
    }

    if (!isBlank(body.guestPassport()) && isBlank(body.guestCountry())) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "guestCountry is required when guestPassport is provided");
    }

    Guest guest = new Guest(
            body.guestName(),
            body.guestEmail(),
            body.guestCpf(),
            body.companyCnpj(),
            body.companyName(),
            body.guestPassport(),
            body.guestCountry());
    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

